def validate_generated_code():
    _get_ptx_module().function("layernorm_forward")

class _LayerNormParams(nn.Module):
    def __init__(self, normalized_shape):
        super().__init__()
        self.weight = nn.Parameter(torch.ones(tuple(normalized_shape)))
        self.bias = nn.Parameter(torch.zeros(tuple(normalized_shape)))

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.ln = _LayerNormParams(self.normalized_shape)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        y = torch.empty(x.shape, dtype=x.dtype, device=x.device)
        rows = x.shape[0]
        n = 1
        for d in self.normalized_shape:
            n *= int(d)
        module = _get_ptx_module()
        module.launch(
            "layernorm_forward",
            grid=(rows, 1, 1),
            block=(1024, 1, 1),
            arguments=[x, y, self.ln.weight, self.ln.bias, i32(n), i32(rows), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y
